export type { Token } from "./token.js";
interface Eff<A, E, R> { readonly value: A; readonly error: E; readonly service: R; }
/** Services required by a tool. */
export type Services<T> = ServicesOf<T, []>;
type ServicesOf<T, Depth extends ReadonlyArray<unknown>> = Depth["length"] extends 8 ? never : T extends { readonly _tag: "Tool"; readonly execute: (input: unknown) => Eff<unknown, unknown, infer R> } ? R : T extends object ? string extends keyof T ? ServicesOf<T[string], [...Depth, unknown]> : ServicesOf<T[keyof T], [...Depth, unknown]> : never;
